#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include "header.h"

void stream_file(const char* path, void (*chunk_cb)(const uint8_t*, size_t, void*), void* user){
  FILE* f = fopen(path, "rb");
  if (!f) { chunk_cb(NULL, 0, user); return; }
  uint8_t buf[4096];
  size_t n;
  while ((n = fread(buf, 1, sizeof(buf), f)) > 0){
    chunk_cb(buf, n, user);
  }
  fclose(f);
  // end signal
  chunk_cb(NULL, 0, user);
}
